### 一、数组的三条本质

- **同类型、连续存放**：`int a[10];` 是 10 个 int 紧贴在一起（本机 40 字节），`a[0]` 是首元素，`a[9]` 是末元素，中间没有空隙。
- **长度必须是编译期常量**：写 `int a[10]`，或用 `#define N 1005` 后写 `int a[N]`。不要写 `int n; scanf("%d", &n); int a[n];`——这是变长数组（VLA），本课程不允许，评测机上容易直接导致 RE。
- **数组名是首元素地址**：`a` 与 `&a[0]` 值相同；`sizeof(a)` 是"整个数组占多少字节"，这两件事要分清楚。

### 二、一维、二维、字符数组其实是同一件事

| 写法 | 单元是什么 | 元素个数 | `sizeof` | 内存排布 |
|---|---|---|---|---|
| `int a[5]` | 一个 int | 5 | 20 | 一行 5 个 |
| `int b[3][4]` | 一个 int | 12 | 48 | 3 行 × 4 列，按行存储 |
| `char s[8]` | 一个 char | 8 | 8 | 能装 7 个字符 + `'\0'` |
| `char t[3][10]` | 一行 10 个 char | 30 | 30 | 3 个字符串，每个最长 9 字符 |

二维数组 `b[i][j]` 换算成一维就是 `b[i * 4 + j]`（行优先 / 按行存储），所以**按行遍历比按列遍历快**，因为内存连续、缓存命中率高。字符数组只是"元素类型为 char 的数组"，它之所以特殊，是因为 C 语言给"以 `'\0'` 结尾的字符数组"起了名字——字符串。

### 三、初始化陷阱（机考最常见的丢分点）

```c
int a[5];              /* 局部数组：5 个不确定的垃圾值，必须自己赋 */
int b[5] = {0};        /* 只写一个 0：5 个元素全部为 0（推荐） */
int c[5] = {1, 2};     /* 前两个是 1、2，后面三个自动补 0 */
int d[3][4] = {{0}};   /* 二维清零最省事的写法 */
char s1[] = "abc";     /* 长度 4：'a' 'b' 'c' '\0' */
char s2[3] = "abc";    /* 长度刚好 3，没有位置放 '\0'——它不是字符串！ */
char s3[5] = "abc";    /* 后两个位置自动补 '\0' */
```

- 全局数组、`static` 数组**自动清零**；局部数组**不清零**。题目要求初始化为 0 时，写 `= {0}`，或者把数组定义在 `main` 外面。
- `memset(a, 0, sizeof(a))` 只能用来清零或填 `-1`；用它把 int 数组填成 1 是错的，因为 `memset` 按字节填充。
- 大数组（如 `int a[1000000]`）一定定义在 `main` 外面：局部变量在栈上，栈只有几 MB，直接爆栈 RE。

### 四、下标越界：C 不会拦住你，只会悄悄改坏别的变量

```c
int a[5] = {1, 2, 3, 4, 5};
int sum = 0, i;

for (i = 0; i <= 5; i++)   /* 错：i == 5 时越界，读到"邻居"内存 */
    sum += a[i];

for (i = 0; i < 5; i++)    /* 对：合法下标是 0 ~ 4 */
    sum += a[i];
```

越界的典型信号有三种：程序看起来正常但答案偏大偏小、旁边某个变量被莫名改掉、直接运行时就崩。**写循环前先问自己三句**：下标从几开始？到几结束（用 `<` 还是 `<=`）？数组容量够不够（读入时多开 5 个位置做冗余）？

### 五、数组作函数参数：长度会"丢掉"

```c
#include <stdio.h>
#define N 10

void show(int a[], int n)   /* 形参 int a[] 等价于 int *a */
{
    printf("%d\n", (int)sizeof(a));   /* 指针大小（8 或 4），绝不是 40 */
    for (int i = 0; i < n; i++)
        printf("%d ", a[i]);
    printf("\n");
}

void addOne(int a[], int n)  /* 传的是地址，函数里改的就是原数组 */
{
    for (int i = 0; i < n; i++)
        a[i]++;
}

int main(void)
{
    int a[N] = {1, 2, 3};
    show(a, 3);      /* 数组名就是首地址，不用写 & */
    addOne(a, 3);
    show(a, 3);
    return 0;
}
```

三条规则背下来：

1. **长度必须单独传**：函数里的 `sizeof(a)` 会退化成指针大小，一律按 `(数组, 长度)` 双参数约定。
2. **在函数里改数组会影响调用者**（因为传的是地址）；形参写 `const int a[]` 表示只读，既防改错又说明意图。
3. **二维数组传参必须写明列数**：`void f(int a[][N], int m)` 合法，`void f(int a[][], int m)` 编译不过。

### 六、五种必背遍历模式

```c
/* 1) 最值 + 最值下标 */
int findMax(const int a[], int n, int *posOut)
{
    int i, max = a[0];
    *posOut = 0;
    for (i = 1; i < n; i++)
        if (a[i] > max) {
            max = a[i];
            *posOut = i;
        }
    return max;
}
```

```c
/* 2) 原地逆置：双指针向中间靠 */
void reverse(int a[], int n)
{
    int i = 0, j = n - 1, t;
    while (i < j) {
        t = a[i];
        a[i] = a[j];
        a[j] = t;
        i++;
        j--;
    }
}
```

```c
/* 3) 循环左移 k 位：三次逆置，不用额外数组 */
static void reverseRange(int a[], int l, int r)
{
    int t;
    while (l < r) {
        t = a[l];
        a[l] = a[r];
        a[r] = t;
        l++;
        r--;
    }
}

void rotateLeft(int a[], int n, int k)
{
    if (n <= 0) return;
    k %= n;
    reverseRange(a, 0, k - 1);
    reverseRange(a, k, n - 1);
    reverseRange(a, 0, n - 1);
}
```

```c
/* 4) 计数桶：值域小时用数组当"哈希表" */
int countValue(const int a[], int n, int val, int maxValue)
{
    int i;
    int cnt[1005] = {0};       /* 局部数组必须 = {0} 清零 */
    for (i = 0; i < n; i++)
        if (a[i] >= 0 && a[i] <= maxValue)
            cnt[a[i]]++;
    if (val < 0 || val > maxValue) return 0;
    return cnt[val];
}
```

```c
/* 5) 双指针压紧：删除所有等于 val 的元素，返回新长度 */
int removeValue(int a[], int n, int val)
{
    int i, k = 0;
    for (i = 0; i < n; i++)
        if (a[i] != val)
            a[k++] = a[i];
    return k;
}
```

### 七、考点提示

- 二维题（转置、鞍点、蛇形、矩阵变换）先确定"谁是行谁是列"，再写边界；输出时注意题面是否从 1 开始。
- 一维题的常见变式：最长平台、连续子序列、去重、统计众数、求次大值——都是"一次遍历 + 几个状态变量"。
- 读入 n 个数前先判断 `if (scanf("%d", &n) != 1) return 0;`，防止空输入时使用未初始化变量。

### 一、C 字符串只有一条规则：以 `'\0'` 结尾

`'\0'` 是 ASCII 码为 0 的字符，作用只有一个——标记"字符串到这里结束"。它不算内容，但**占一个字节**。

- `char s[10];` 最多存 **9** 个可见字符，最后一个位置留给 `'\0'`。题面写"长度不超过 100"，数组就要开 `105`。
- `strlen(s)` 数到 `'\0'` 为止，**不把 `'\0'` 算进去**；`sizeof(s)` 数的是数组容量，两者完全不同。
- 忘了写 `'\0'`：`printf("%s", s)` 会一直往后读，输出乱码甚至崩溃。所以手工逐字符填完后，务必补一句 `s[k] = '\0';`。
- `'\0'` 与 `'0'` 不是一回事：前者是结束标记（数值 0），后者是数字字符（数值 48）。

### 二、四种读入方式对比（这是最容易翻车的地方）

| 方式 | 读什么 | 遇到空格 | 换行符 | 典型用法 |
|---|---|---|---|---|
| `scanf("%s", s)` | 一个不含空白的单词 | 停止，下一个 `%s` 继续读 | 留在缓冲区 | 读单词、读学号 |
| `fgets(s, sizeof(s), stdin)` | 一整行（含空格） | 照读 | **读进来并留在串尾** | 读含空格的句子 |
| `scanf(" %c", &ch)` | 一个字符 | 前导空格被跳过 | 不读 | 逐个字符处理 |
| `getchar()` | 一个字符（含空格、换行） | 照读 | 会读到 | 清缓冲、逐字符扫描 |

```c
#include <stdio.h>
#include <string.h>

int main(void)
{
    char word[32];
    char line[128];
    int n;

    scanf("%d", &n);                    /* 缓冲区里残留一个 '\n' */
    scanf("%s", word);                  /* %s 自动跳过前导空白，能吃掉那个 '\n' */
    getchar();                          /* 下一句要读整行，先手动清掉行尾换行 */
    if (fgets(line, sizeof(line), stdin) != NULL) {
        line[strcspn(line, "\n")] = '\0';   /* 去掉 fgets 读进来的换行 */
        printf("[%s] [%s]\n", word, line);
    }
    return 0;
}
```

三个高频坑：

1. `scanf("%d", &n)` 之后直接 `scanf("%c", &ch)`，会读到上一行的 `'\n'`。解决：写成 `scanf(" %c", &ch)`（`%c` 前加一个空格）或先 `getchar()`。
2. `fgets` 一定把行尾 `'\n'` 读进来，比较字符串前要用 `strcspn` 或手工删掉，否则 `"abc\n" != "abc"`。
3. 循环里混用 `scanf` 和 `fgets`，最常见的就是"少读一行"。记口诀：**数字用 `scanf`，整行先清换行**。

### 三、四个必会函数 + 手写实现

| 函数 | 作用 | 返回值 |
|---|---|---|
| `strlen(s)` | 求长度（不含 `'\0'`） | 长度 |
| `strcpy(dst, src)` | 复制（含 `'\0'`） | `dst` |
| `strcat(dst, src)` | 把 src 拼到 dst 末尾 | `dst` |
| `strcmp(a, b)` | 字典序比较 | 负数 / 0 / 正数 |

```c
#include <stddef.h>

size_t my_strlen(const char *s)
{
    size_t n = 0;
    while (s[n] != '\0')
        n++;
    return n;
}

char *my_strcpy(char *dst, const char *src)
{
    char *p = dst;
    while ((*p++ = *src++) != '\0')
        ;
    return dst;
}

char *my_strcat(char *dst, const char *src)
{
    char *p = dst;
    while (*p)
        p++;                    /* 先走到 dst 的末尾 '\0' 处 */
    while ((*p++ = *src++) != '\0')
        ;
    return dst;
}

int my_strcmp(const char *a, const char *b)
{
    while (*a && *a == *b) {
        a++;
        b++;
    }
    return (int)(unsigned char)*a - (int)(unsigned char)*b;
}
```

- 想"取前 k 个字符"用 `strncpy(dst, src, k)`，但**它不保证补 `'\0'`**，要自己写 `dst[k] = '\0'`。
- 查找：`strchr(s, ch)` 返回首次出现位置的指针（找不到返回 `NULL`），`strstr(s, sub)` 找子串。
- 比较字符串**只能**用 `strcmp(a, b) == 0`，`a == b` 比较的是两个地址，永远是假的。
- 别把 `strcat` 拼到字面量上：`char *s = "abc"; strcat(s, "d");` 会写只读内存，直接崩。

### 四、常见字符串题型清单

- **统计类**：字母 / 数字 / 空格 / 其他字符各多少个；每个字母出现几次（用 `cnt[26]` 桶）；最长单词、最短单词。
- **变换类**：大小写互转、凯撒密码、逆序输出、句子反序（单词顺序颠倒）。
- **判断类**：回文、是不是数字串、括号是否匹配（用一个数组当栈，`top` 指针压入弹出）。
- **查找与删除**：子串出现位置与次数、删除指定字符、删除所有空格、替换字符。
- **排序类**：对若干字符串按字典序排序（用 `strcmp` 比较、`strcpy` 交换，或用指针数组）。
- **拆分类**：按空格 / 逗号切词并逐个输出，记录每个单词的首地址与长度。

### 五、实用小模板

```c
#include <string.h>

/* 删除字符串中所有空格，原地完成 */
void removeSpaces(char *s)
{
    int i = 0, k = 0;
    while (s[i] != '\0') {
        if (s[i] != ' ')
            s[k++] = s[i];
        i++;
    }
    s[k] = '\0';
}

/* 判断回文：双指针从两端向中间比 */
int isPalindrome(const char *s)
{
    int i = 0;
    int j = (int)strlen(s) - 1;
    while (i < j) {
        if (s[i] != s[j])
            return 0;
        i++;
        j--;
    }
    return 1;
}
```

注意：`removeSpaces` 用的是"读指针 i、写指针 k"的双指针压紧法，和数组去重是同一个套路，只是元素换成了字符。凡是要"原地"完成、不许多开数组的题目，基本都用这种写法。

### 六、考点提示

- 题面写"一行"，就用 `fgets`；写"一个单词 / 不含空格"，就用 `scanf("%s")`。用错读入方式，样例永远对不上。
- 输出逆序、反向打印类题目注意：不要把 `'\0'` 打印出来，下标从 `len - 1` 递到 `0`。
- 字符数组开大 5 个位置；`strcat` 前确认目标数组够长，否则越界写会改坏别的变量。

### 一、定义、声明、调用三件事

- **定义**：写出函数体。`返回类型 函数名(参数表) { ... }`。
- **声明（原型）**：只写头，如 `int add(int a, int b);`。定义写在调用之后时，必须先在前面声明，否则编译器按 C89 规则猜类型，容易出链接错误。
- **调用**：`add(3, 4)`。实参的个数、类型要和形参对得上。
- 无参数写 `void`：`int f(void);` 表示"不接受参数"，写 `int f();` 是"参数不确定"，两码事。
- `return` 只能返回**一个**值；`void` 函数可以 `return;` 提前结束。

```c
#include <stdio.h>

int add(int a, int b);          /* 声明 */

int main(void)
{
    printf("%d\n", add(3, 4));  /* 调用 */
    return 0;
}

int add(int a, int b)           /* 定义 */
{
    return a + b;
}
```

### 二、值传递：形参只是实参的副本

这是函数题的**第一考点**。函数收到的是一份拷贝，改形参不会改实参。想让函数改调用者的变量，必须传地址。

```c
#include <stdio.h>

void swapWrong(int x, int y)    /* 交换的只是副本，调用者毫无感觉 */
{
    int t = x;
    x = y;
    y = t;
}

void swapRight(int *px, int *py)  /* 传地址，才是真交换 */
{
    int t = *px;
    *px = *py;
    *py = t;
}

int main(void)
{
    int a = 1, b = 2;
    swapWrong(a, b);
    printf("a=%d b=%d\n", a, b);   /* 1 2，没变 */
    swapRight(&a, &b);
    printf("a=%d b=%d\n", a, b);   /* 2 1，变了 */
    return 0;
}
```

### 三、数组作参数

- `void f(int a[], int n)` 与 `void f(int *a, int n)` 完全等价，**长度必须另外传**。
- 传数组传的是首地址，函数里改数组会改到调用者；只读时写 `const int a[]`。
- 二维数组只能省第一维：`void f(int a[][N], int m)`，其中 `N` 必须是常量。
- 结构体作参数默认也是值传递（整块拷贝，大结构体开销大），一般写 `const Student *s` 传指针。

### 四、返回多个值的两种做法

**做法一：指针作为输出参数**（最常用，和题目接口一致）。

```c
void stat2(const int a[], int n, int *pmin, int *pmax)
{
    int i;
    *pmin = *pmax = a[0];
    for (i = 1; i < n; i++) {
        if (a[i] < *pmin) *pmin = a[i];
        if (a[i] > *pmax) *pmax = a[i];
    }
}
```

**做法二：返回一个结构体**（把多个值打包，语义更清楚）。

```c
typedef struct {
    int minv;
    int maxv;
} MinMax;

MinMax stat(const int a[], int n)
{
    MinMax r;
    int i;
    r.minv = r.maxv = a[0];
    for (i = 1; i < n; i++) {
        if (a[i] < r.minv) r.minv = a[i];
        if (a[i] > r.maxv) r.maxv = a[i];
    }
    return r;    /* 按值返回整个结构体，合法且安全 */
}
```

**不要用全局变量传结果**：题目会多次调用你的函数，全局累加器会"多做一遍"，是函数题最常见的错误来源。

### 五、局部、静态、全局变量与作用域

| 类别 | 定义位置 | 初值 | 生命周期 | 可见范围 |
|---|---|---|---|---|
| 局部变量 | 函数内 | **随机值** | 本次调用 | 本函数块内 |
| 静态局部 `static` | 函数内 | 0 | **整个程序** | 仅本函数 |
| 全局变量 | 所有函数外 | 0 | 整个程序 | 其后的所有函数 |
| 全局静态 `static` | 文件级 | 0 | 整个程序 | 仅本文件 |

```c
#include <stdio.h>

int g_count;                 /* 全局：自动为 0，所有函数可见 */

void counter(void)
{
    int local = 0;           /* 局部：每次调用重建 */
    static int calls = 0;    /* 静态局部：只创建一次，跨调用保留 */
    local++;
    calls++;
    g_count++;
    printf("local=%d calls=%d\n", local, calls);
}

int main(void)
{
    counter();               /* local=1 calls=1 */
    counter();               /* local=1 calls=2 */
    counter();               /* local=1 calls=3 */
    printf("g_count=%d\n", g_count);
    return 0;
}
```

要点：

- `static` 局部变量常用于"只初始化一次"的场合，但它让函数不可重入，递归里慎用。
- 大数组放全局（或 `static`）既避免爆栈，又自动清零。
- 变量命名避免与库函数同名（`index`、`y1`、`time` 之类）。

### 六、递归 vs 迭代怎么选

| 场景 | 建议 |
|---|---|
| 问题有明显"自相似"结构（树的遍历、汉诺塔、全排列、表达式求值） | 递归，代码短 |
| 简单累加 / 计数 / 遍历数组 | 迭代，更快更安全 |
| 递归深度可能超过几千（如 n 很大） | 迭代，否则爆栈 |
| 存在大量重复子问题（斐波那契） | 迭代 / 递推，或记忆化 |

原则是：**能一眼写出递推式的用循环，结构天然分层的用递归**。考试中递归题按题目要求写，别自作聪明改迭代（题面要求"用递归实现"就必须递归）。

### 七、考点提示

- 函数题（PTA `6-xx`）改编成完整程序时，注意 `main` 里读入、调用、输出三段要齐全，接口签名与题面**逐字符一致**。
- 判素数、求 gcd、进制转换这类函数，注意边界：`n < 2`、`b == 0`、`n == 0`。
- 一个函数只做一件事；名字能看出功能（`isPrime`、`getDigit`、`printPerfect`），阅卷和自查都省时间。

### 一、递归的三要素

1. **出口（终止条件）**：最简单情形直接给出答案，例如 `n == 1`、`n == 0`、`left > right`。
2. **递归式**：把规模 n 的问题化为规模更小（n-1、n/2、少一个元素）的同类问题。
3. **向出口靠近**：每次递归调用都必须让参数朝出口方向变小，否则无限递归 → 栈溢出。

写递归时按这个顺序自问：**出口写了吗？规模变小了吗？返回值怎么组合？**

### 二、递归求值

```c
long long fact(int n)
{
    if (n <= 1) return 1;          /* 出口 */
    return (long long)n * fact(n - 1);   /* 递归式 */
}

long long mypow(int x, int n)      /* 快速幂：O(log n) 层递归 */
{
    long long half;
    if (n == 0) return 1;
    half = mypow(x, n / 2);
    if (n % 2 == 0)
        return half * half;
    return half * half * x;
}
```

注意 `fact(13)` 已经超出 int 范围，返回值一律用 `long long` 并用 `%lld` 输出。

### 三、递归求最值

```c
int maxOf(const int a[], int n)
{
    int m;
    if (n == 1) return a[0];        /* 出口：只剩一个元素 */
    m = maxOf(a, n - 1);            /* 先求前 n-1 个的最大值 */
    return a[n - 1] > m ? a[n - 1] : m;
}
```

同类变式：递归求和、递归求平均值、递归统计满足条件的元素个数，套路都是"先处理前 n-1 个，再和最后一个合并"。

### 四、进制转换与逆序输出：借"递归回来的顺序"天然反向

```c
void toBase(int n, int base)        /* 2 <= base <= 16，n 为非负 */
{
    const char *digits = "0123456789ABCDEF";
    if (n >= base)
        toBase(n / base, base);     /* 先递归处理高位 */
    printf("%c", digits[n % base]); /* 回来时再输出低位，顺序自动正确 */
}
```

```c
/* 逆序输出各位数字：先输出末位，再递归处理高位 */
void printReverse(long long n)
{
    if (n < 0) {
        printf("-");
        n = -n;
    }
    printf("%lld", n % 10);
    if (n >= 10)
        printReverse(n / 10);
}
```

若题目要求"逆序后不输出前导 0"（如 120 逆序输出 21），先算出逆序数值再输出更省事：`rev = rev * 10 + n % 10`。

### 五、gcd、斐波那契、汉诺塔

```c
int gcd(int a, int b)
{
    return b == 0 ? a : gcd(b, a % b);   /* 一行递归，欧几里得算法 */
}
```

```c
long long fib(int n)                    /* 只适合 n <= 40 演示递归 */
{
    if (n <= 2) return 1;
    return fib(n - 1) + fib(n - 2);
}
```

```c
void hanoi(int n, char from, char to, char via, int *pcount)
{
    if (n == 0) return;
    hanoi(n - 1, from, via, to, pcount);       /* 把上面 n-1 个挪到中转柱 */
    printf("%d:%c->%c\n", n, from, to);        /* 移动最大盘 */
    (*pcount)++;
    hanoi(n - 1, via, to, from, pcount);       /* 再把 n-1 个挪到目标柱 */
}
```

汉诺塔移动次数为 `2^n - 1`，n = 64 时早已超出 `long long`，题目一般只问到 n ≤ 30。

### 六、全排列模板（回溯法）

```c
#include <stdio.h>

#define N 10

int a[N];        /* 当前排列 */
int used[N + 1]; /* used[i] 表示数字 i 是否已被使用 */

void perm(int depth, int n)
{
    int i;
    if (depth == n) {                    /* 出口：凑满一个排列 */
        for (i = 0; i < n; i++)
            printf(i ? " %d" : "%d", a[i]);
        printf("\n");
        return;
    }
    for (i = 0; i < n; i++) {
        if (used[i]) continue;
        used[i] = 1;                     /* 做选择 */
        a[depth] = i + 1;
        perm(depth + 1, n);              /* 进入下一层 */
        used[i] = 0;                     /* 回溯：撤销选择 */
    }
}
```

三点记住：**"做选择 → 递归 → 撤销选择"** 是回溯的固定骨架；`used` 数组是状态；每层都要能恢复现场，否则结果变少。

### 七、递归树与栈：为什么慢、为什么爆

- 每次调用都会压入一个**栈帧**，保存参数、返回地址、局部变量。函数返回时弹出，所以递归天生占内存。
- `fib(n)` 的递归树有约 `2^n` 个结点，大量重复计算：`fib(30)` 已经调用上百万次，`fib(45)` 要等好几秒。改成递推（数组或三个变量滚动）立刻变成 O(n)。
- 递归深度过大会**栈溢出**：Windows 默认栈约 1MB，每帧几十字节，深度上万就到极限。深度可能上万时（如扫描 10 万个元素）必须写循环。
- 递归转迭代的通用手法：把中间结果存进数组（递推 / 动态规划），或用自己开的数组模拟栈。

| 维度 | 递归 | 迭代 |
|---|---|---|
| 代码长度 | 短，贴近定义 | 略长 |
| 效率 | 有调用开销，可能重复计算 | 无额外开销 |
| 风险 | 栈溢出 | 循环边界写错 |
| 适用 | 分治、回溯、树、汉诺塔 | 线性扫描、累加、递推 |

### 八、考点提示

- 题面写"请用递归实现"，就必须出现函数自己调用自己，用循环会判错。
- 递归题最容易错的两处：**出口的边界值**（`n == 0` 还是 `n == 1`）和**参数有没有变小**。
- 递归求值类题（实验 6_1、6_2）先手算前 3 项，把公式写清再敲代码，比调试快得多。
- 递归里不要用静态/全局计数器做中间结果，除非题目明确多次独立调用不会互相影响。

### 一、定义与 `typedef`

结构体把"属于同一个对象的一组数据"打包成一个新类型。

```c
#include <stdio.h>
#include <string.h>

typedef struct {
    char id[16];
    char name[32];
    int  score;
} Student;              /* 以后 Student 就是类型名，用起来像 int */
```

- 有了 `typedef`，定义变量写 `Student s;`；没有就得写 `struct Student s;`，考试两种都可能出现。
- 成员用点访问：`s.score = 90;`、`strcpy(s.name, "Tom");`（字符数组**不能**直接赋值）。
- `sizeof(Student)` 可能大于成员之和（对齐填充），不要用它计算"有几个成员"。

### 二、嵌套与结构体数组

```c
#define N 100

typedef struct {
    int y, m, d;
} Date;

typedef struct {
    char name[32];
    Date birth;        /* 嵌套：结构体里放结构体 */
    int  score;
} Person;

Person ps[N];          /* 结构体数组：100 个人连续存放 */

/* 访问方式：逐层点下去 */
/* ps[i].birth.y 就是第 i 个人的出生年份 */
```

结构体数组就是"一次定义一批对象"，取值仍是两次下标：`ps[i].score`。读取时注意 `scanf("%s", ps[i].name)`——数组名本身已是地址，不加 `&`。

### 三、结构体指针与 `->`

```c
typedef struct {
    char id[16];
    char name[32];
    int  score;
} Student;

void printStudent(const Student *s)
{
    printf("%s %s %d\n", s->id, s->name, s->score);
    /* s->score 等价于 (*s).score；漏掉括号写成 *s.score 是错的 */
}

void raiseScore(Student *s, int delta)
{
    s->score += delta;      /* 传指针才能真正改到调用者的结构体 */
}
```

- `s->score` 是 `(*s).score` 的简写。
- 结构体传参默认整块拷贝，大结构体（含字符串数组）建议传 `const Student *`，既快又安全。
- 指针数组 + 结构体是最常见的"免拷贝"组合：`Student *idx[N]`。

### 四、结构体排序：Swap / Comp / Sort 三段式

实验 11 的经典结构：交换、比较、排序三个函数分离开，考试常直接给你前两个的签名要你补第三个。

```c
typedef struct {
    char id[16];
    int  total, ce, ws;     /* 综合成绩、机试、加权 */
} STUDENT;

void Swap(STUDENT *s1, STUDENT *s2)
{
    STUDENT t = *s1;        /* 结构体可以整体赋值 */
    *s1 = *s2;
    *s2 = t;
}

int Comp(const STUDENT *s1, const STUDENT *s2)
{
    if (s1->total != s2->total)          /* 第一关键字：总分降序 */
        return s1->total > s2->total;
    return s1->ce > s2->ce;              /* 第二关键字：机试降序 */
}

void Sort(STUDENT a[], int size)
{
    int i, j;
    for (i = 0; i < size - 1; i++)
        for (j = 0; j < size - 1 - i; j++)
            if (!Comp(&a[j], &a[j + 1]))     /* 前面不比后面大，就交换 */
                Swap(&a[j], &a[j + 1]);
}
```

多关键字排序的解题公式：**先按第一关键字比较，相等再比第二关键字，再相等比第三关键字**。写 `Comp` 时用 `if` 逐层落下，别堆成一长串 `&&`。

### 五、结构体 + 动态内存

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    char id[16];
    int  score;
} Stu;

int main(void)
{
    int n, i;
    Stu *arr;

    if (scanf("%d", &n) != 1 || n <= 0)
        return 0;
    arr = (Stu *)malloc((size_t)n * sizeof(Stu));
    if (arr == NULL) {
        printf("no memory\n");
        return 0;
    }
    for (i = 0; i < n; i++)
        scanf("%s %d", arr[i].id, &arr[i].score);
    for (i = 0; i < n; i++)
        printf("%s %d\n", arr[i].id, arr[i].score);

    free(arr);
    arr = NULL;
    return 0;
}
```

注意 `malloc` 的写法顺序：**强制类型转换 → 元素个数 × `sizeof(元素类型)` → 判空**。用完 `free`，并把指针置 `NULL` 防止误用。

### 六、枚举与联合（概念题考点）

```c
typedef enum { MON = 1, TUE, WED, THU, FRI, SAT, SUN } WeekDay;

union Value {
    int    i;
    double d;
    char   s[8];
};
```

| 类型 | 本质 | 长度 | 用途 |
|---|---|---|---|
| `enum` | 一组整型常量（默认从 0 递增） | 同 `int` | 让状态、星期、性别更好读 |
| `union` | 所有成员**共用**一块内存 | 最大成员的大小 | 省内存，同一时刻只用一个成员 |
| `struct` | 成员**各占**内存依次排列 | 成员之和（含对齐） | 组织一个对象的多个属性 |

枚举变量本质是整数，可以直接用于 `switch`；`union` 期末一般只出"改一个成员会影响另一个成员"这类阅读题。

### 七、考点提示

- 结构体数组读入：`scanf("%s %d %d", a[i].id, &a[i].ce, &a[i].ws);`——字符串不加 `&`，整数必须加。
- 排序稳定性的实践意义：同分同学按学号输出时，用**插入排序**或带第二关键字的冒泡。
- 结构体不能直接用 `==` 比较（除非逐成员比较），也不能直接 `printf`，要逐成员输出。
- 学生信息管理系统类题（增删改查）用"结构体数组 + 计数器 size"就能实现，不必上动态内存。
- 实验 11 那套综合成绩排名题，通常给出 `Swap`、`Comp`、`Sort` 三个函数声明，只让你填其中一个。填之前先看清题意：总分怎么算（机试 + 加权，还是各占 50%）、总分相同时比什么、输出时三个整数是什么顺序。接口签名必须与题面**逐字符一致**，多一个 `const` 都可能编译不过。
- 结构体数组作为函数参数时同样会退化成指针，所以 `void Sort(STUDENT a[], int size)` 里 `sizeof(a)` 也是指针大小，长度只能用 `size`。
- 结构体成员里如果放了字符数组，读入时注意数组名不加 `&`；如果放的是 `char *`，则必须先分配内存才能读入，这是最容易 RE 的一步。

### 一、先明确一件事

**本学期期末机考只考 C 语言**，本节内容不会以 C++ 代码的形式出现在考卷上。它有三个作用：第一，帮你理解教材最后一章在讲什么；第二，把"结构体 + 一组操作函数"这种 C 的写法当成"类"来读，做实验 11 的综合题会更清楚；第三，为后续的面向对象课程铺路。C++ 内容仅出现在下面这张对照表里，题目和答案一律用 C。

### 二、概念对照：C 的写法 ↔ 面向对象的说法

| 面向对象概念 | C++ 里的写法 | C 语言里的对应做法 |
|---|---|---|
| 数据成员 | `class S { int size; };` 里的成员变量 | 结构体成员 `struct S { int size; };` |
| 成员函数 | `void add(Student s);` 写在类里 | 独立函数，第一个参数是结构体指针：`void S_add(S *p, Student s);` |
| 构造函数 | `S() { size = 0; }` 自动调用 | 初始化函数 `void S_init(S *p) { p->size = 0; }` 手工调用 |
| 析构函数 | `~S()` 自动释放 | `void S_destroy(S *p)` 里手工 `free` |
| 封装 | `private:` 外部不能访问 | 靠约定：函数名加前缀 + `static` 限制文件内可见 |
| 对象调用 | `obj.add(x)`，隐式传 `this` | `S_add(&obj, x)`，显式传地址，就是 `this` |
| 访问成员 | `obj.size`、`ptr->size` | `obj.size`、`ptr->size`（语法一样） |
| 访问控制 | `public` / `private` / `protected` | 无关键字，用头文件 + `static` + 命名约定模拟 |
| 继承多态 | `class B : public A` | 无对应，用函数指针模拟（了解即可） |

一句话总结：**类 = 数据 + 操作这些数据的函数，再加"外部只能通过函数访问数据"这条约定**。C 里没有 `class` 关键字，但把"结构体 + 以它为第一个参数的函数族"看成一个整体，就已经是类的雏形。

### 三、C 版「学生管理类」完整框架

下面这段代码把封装思想落实成 C：数据放在结构体里，全部操作通过 `Manager_` 前缀的函数进行，外部不直接碰 `data` 与 `size`。这就是实验 11 综合题（学生信息管理系统）最稳的写法。

```c
#include <stdio.h>
#include <string.h>

#define MAX_STU 100

typedef struct {
    char id[16];
    char name[32];
    int  math, eng, cs;      /* 数据成员：外部不直接改 */
} Student;

typedef struct {
    Student data[MAX_STU];   /* 内部存储方式对外隐藏 */
    int     size;            /* 当前人数，相当于"对象的状态" */
} StudentManager;

/* 初始化：对应构造函数 */
void Manager_Init(StudentManager *m)
{
    m->size = 0;
}

/* 内部辅助函数：static 表示只在本文件可见，相当于 private */
static int Manager_Find(const StudentManager *m, const char *id)
{
    int i;
    for (i = 0; i < m->size; i++)
        if (strcmp(m->data[i].id, id) == 0)
            return i;
    return -1;
}

/* 增加：成功返回 1，失败返回 0 */
int Manager_Add(StudentManager *m, const Student *s)
{
    if (m->size >= MAX_STU) return 0;
    if (Manager_Find(m, s->id) >= 0) return 0;   /* 学号已存在 */
    m->data[m->size] = *s;
    m->size++;
    return 1;
}

/* 删除：后面的元素整体前移一格 */
int Manager_Del(StudentManager *m, const char *id)
{
    int i = Manager_Find(m, id);
    int k;
    if (i < 0) return 0;
    for (k = i; k < m->size - 1; k++)
        m->data[k] = m->data[k + 1];
    m->size--;
    return 1;
}

/* 修改成绩 */
int Manager_Update(StudentManager *m, const char *id, int math, int eng, int cs)
{
    int i = Manager_Find(m, id);
    if (i < 0) return 0;
    m->data[i].math = math;
    m->data[i].eng  = eng;
    m->data[i].cs   = cs;
    return 1;
}

/* 查询平均分：找不到返回 -1 */
double Manager_Average(const StudentManager *m, const char *id)
{
    int i = Manager_Find(m, id);
    if (i < 0) return -1.0;
    return (m->data[i].math + m->data[i].eng + m->data[i].cs) / 3.0;
}

/* 显示某个学生的三行信息（与题面输出格式一致） */
void Manager_ShowOne(const StudentManager *m, int i)
{
    printf("Student ID:%s\n", m->data[i].id);
    printf("Name:%s\n", m->data[i].name);
    printf("Average Score:%.1f\n",
           (m->data[i].math + m->data[i].eng + m->data[i].cs) / 3.0);
}

/* 显示全部 */
void Manager_Show(const StudentManager *m)
{
    int i;
    for (i = 0; i < m->size; i++)
        printf("%s %s %d %d %d\n", m->data[i].id, m->data[i].name,
               m->data[i].math, m->data[i].eng, m->data[i].cs);
}

int main(void)
{
    StudentManager mgr;
    Student s;
    int n, op, i, math, eng, cs, pos;

    Manager_Init(&mgr);                  /* 一定要先初始化，否则 size 是垃圾值 */
    if (scanf("%d", &n) != 1) return 0;
    for (i = 0; i < n; i++) {
        if (scanf("%d", &op) != 1) break;
        if (op == 1) {
            scanf("%s %s %d %d %d", s.id, s.name, &s.math, &s.eng, &s.cs);
            printf(Manager_Add(&mgr, &s) ? "Add success\n" : "Students already exist\n");
        } else if (op == 2) {
            scanf("%s", s.id);
            printf(Manager_Del(&mgr, s.id) ? "Delete success\n" : "Students do not exist\n");
        } else if (op == 3) {
            scanf("%s %d %d %d", s.id, &math, &eng, &cs);
            printf(Manager_Update(&mgr, s.id, math, eng, cs)
                   ? "Update success\n" : "Students do not exist\n");
        } else {
            scanf("%s", s.id);
            pos = Manager_Find(&mgr, s.id);
            if (pos < 0) printf("Students do not exist\n");
            else Manager_ShowOne(&mgr, pos);
        }
    }
    return 0;
}
```

### 四、读这段代码时该看到什么

1. **数据被包起来了**：`mgr.data` 与 `mgr.size` 只在 `Manager_*` 函数里出现，`main` 只调用"动作"，不知道内部是数组还是链表。
2. **每个函数都有"操作对象"参数**：`StudentManager *m` 就是 C 里的 `this`，所以函数名统一加 `Manager_` 前缀，读起来和 `mgr.Add(...)` 感觉接近。
3. **接口与实现分离**：`Manager_Find` 用 `static` 藏起来，外部看不到——这是 C 里最接近 `private` 的手段。
4. **失败有返回值**：`Add` 返回 0/1、`Average` 返回 -1.0，调用者据此输出提示语，而不是靠全局错误码。
5. **初始化的责任在调用者**：没有构造函数，就必须在 `main` 开头显式 `Manager_Init(&mgr);`，否则 `size` 是垃圾值。这是 C 写"类"最容易忘的一步。

### 五、和 C++ 的字面差异（仅作对照，考试不写）

| 目的 | C 写法（考试用这个） | C++ 写法（了解） |
|---|---|---|
| 定义类型 | `struct Student { ... };` | `class Student { ... };` |
| 访问成员 | `p->score`、`p->size` | `p->score`、`p->size`（相同） |
