- 模拟题的核心是把状态写清：现在走到哪、计数到几、下一步该改什么。

```c
/* 日期推进：给定 年 月 日，求下一天 */
int daysOfMonth[13] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};

int isLeap(int y)
{
    return (y % 4 == 0 && y % 100 != 0) || y % 400 == 0;
}

void nextDay(int *py, int *pm, int *pd)
{
    int limit = daysOfMonth[*pm] + ((*pm == 2 && isLeap(*py)) ? 1 : 0);
    (*pd)++;
    if (*pd > limit) {
        *pd = 1;
        (*pm)++;
        if (*pm > 12) {
            *pm = 1;
            (*py)++;
        }
    }
}
```

### 四、前缀和、最大子段和

```c
/* 前缀和：pre[i] 表示 a[0]..a[i-1] 的和，区间 [l, r] 的和 = pre[r+1] - pre[l] */
void buildPrefix(const int a[], int n, long long pre[])
{
    int i;
    pre[0] = 0;
    for (i = 0; i < n; i++)
        pre[i + 1] = pre[i] + a[i];
}
```

```c
/* 最大子段和：Kadane，一遍扫描 O(n) */
long long maxSubArray(const int a[], int n)
{
    long long best = a[0], cur = a[0];
    int i;
    for (i = 1; i < n; i++) {
        cur = (cur > 0) ? cur + a[i] : a[i];   /* 前面的和是负的就丢掉 */
        if (cur > best) best = cur;
    }
    return best;
}
```

### 五、素数筛与素数判定

```c
#define MAXN 1000000

int isComposite[MAXN + 1];   /* 0 表示素数；全局数组自动清零 */

void sieve(int n)
{
    int i, j;
    if (n >= 0) isComposite[0] = 1;
    if (n >= 1) isComposite[1] = 1;
    for (i = 2; i <= n / i; i++)          /* 只筛到 sqrt(n) */
        if (!isComposite[i])
            for (j = i * i; j <= n; j += i)   /* 从 i*i 开始标记 */
                isComposite[j] = 1;
}
```

单次判断素数用试除法即可，循环条件写 `i <= n / i` 避免 `i * i` 溢出。

### 六、进制与高精度入门

- **十进制转 b 进制**：除 b 取余，余数逆序排列。
- **b 进制转十进制**：从高位起 `ans = ans * b + 当前位`。
- **小数部分**：乘 b 取整，顺序排列（期末少见，了解即可）。

```c
#include <string.h>

/* 高精度加法：先按位倒序相加，最后去掉前导 0 并翻转输出 */
void bigAdd(const char *a, const char *b, char *out)
{
    int la = (int)strlen(a), lb = (int)strlen(b);
    int i = la - 1, j = lb - 1, k = 0, carry = 0;
    char tmp[512];

    while (i >= 0 || j >= 0 || carry) {
        int s = carry;
        if (i >= 0) s += a[i--] - '0';
        if (j >= 0) s += b[j--] - '0';
        tmp[k++] = (char)('0' + s % 10);
        carry = s / 10;
    }
    while (k > 0)
        *out++ = tmp[--k];
    *out = '\0';
}
```

### 七、位运算技巧

```c
int popcount(unsigned int x)   { int c = 0; while (x) { c += (int)(x & 1u); x >>= 1; } return c; }
int isPowerOfTwo(unsigned int x) { return x != 0u && (x & (x - 1u)) == 0u; }
int lowbit(int x)              { return x & (-x); }        /* 取出最低位的 1 */
int getBit(int x, int k)       { return (x >> k) & 1; }
int setBit(int x, int k)       { return x | (1 << k); }
int clearBit(int x, int k)     { return x & ~(1 << k); }
int flipBit(int x, int k)      { return x ^ (1 << k); }
```

常用结论：`n & 1` 判奇偶；`n >> 1` 等价整除 2；`x ^ x = 0` 可用于找出唯一出现奇数次的数；`~x = -x - 1`。

### 八、复杂度估算与考点提示

估算复杂度就数"最内层语句执行了多少次"：两层循环各跑 n 次就是 O(n^2)，一层循环加二分就是 O(n log n)。以 n 为参考：n ≤ 1000 时 O(n^2) 完全够用；n 到 10^5 时 O(n^2) 是 10^10 次运算必然 TLE，必须换 O(n) 或 O(n log n)；n 到 10^6 时连 O(n log n) 都要小心，常配前缀和、桶计数。所以**看到数据范围就该反推算法**：范围小可以暴力枚举，范围大就要找公式、二分或一次遍历。

- 排序题注意"按什么关键字排、升序还是降序、相同时怎么办"，先写清规则再动手。
- 二分题一定先排序；题目给的下标是 0 还是 1 起始要看清楚；`mid` 用 `l + (r - l) / 2` 防溢出。
- 数据范围决定类型：和、乘积、斐波那契超过 21 亿就要换 `long long`，格式符同步改 `%lld`。
- 递推题先手算前 3 项并和程序输出对照，能立刻发现初值或下标偏移的错误。
- 模拟题不要追求技巧，把"状态变量"列出来逐个更新，比硬凑一个复杂循环稳得多。
